import{_ as t,o as s,c as i,a4 as r}from"./chunks/framework.BE47AOxC.js";const g=JSON.parse('{"title":"ADR-0070 — Copie distante chiffrée des sauvegardes par restic (S3 compatible, SFTP)","description":"Extrait de docs/adr/0070-copie-distante-chiffree-des-sauvegardes-par-restic.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0070 — Copie distante chiffrée des sauvegardes par restic (S3 compatible, SFTP)","description":"Extrait de docs/adr/0070-copie-distante-chiffree-des-sauvegardes-par-restic.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0070-copie-distante-chiffree-des-sauvegardes-par-restic.md","filePath":"developpeurs/adr/0070-copie-distante-chiffree-des-sauvegardes-par-restic.md"}'),o={name:"developpeurs/adr/0070-copie-distante-chiffree-des-sauvegardes-par-restic.md"};function n(a,e,d,c,u,l){return s(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-0070--copie-distante-chiffrée-des-sauvegardes-par-restic-s3-compatible-sftp" tabindex="-1">ADR-0070 — Copie distante chiffrée des sauvegardes par restic (S3 compatible, SFTP) <a class="header-anchor" href="#adr-0070--copie-distante-chiffrée-des-sauvegardes-par-restic-s3-compatible-sftp" aria-label="Permalink to &quot;ADR-0070 — Copie distante chiffrée des sauvegardes par restic (S3 compatible, SFTP) {#adr-0070--copie-distante-chiffrée-des-sauvegardes-par-restic-s3-compatible-sftp}&quot;">​</a></h1><p><strong>Date :</strong> 13 octobre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> issue #20 (lot 19) ; arbitrages du Product Owner du 13/10/2026 (outil, chiffrement, déclenchement, configuration guidée, surveillance, restauration, preuve en CI) <strong>Amende :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0045-deploiement-par-un-exploitant-non-developpeur">ADR-0045</a>, décision n°6 (« en v1, les sauvegardes restent sur le serveur ») ; <a href="/teuthis-cms-distribution/developpeurs/adr/0052-sauvegarde-nocturne-par-la-pile">ADR-0052</a>, décision n°7 et conséquence « le fichier de sauvegarde n&#39;est pas chiffré au repos » (le chiffrement vient avec la copie qui sort du serveur) <strong>Applique :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0027-adaptateurs-d-exploitation-livres-inactifs">ADR-0027</a> (livré inactif, illisible refusé, injoignable visible)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>L&#39;ADR-0045 a livré la sauvegarde nocturne <strong>sur le serveur</strong> et l&#39;a dit : une copie au même endroit ne protège pas d&#39;une perte du serveur (disque, hébergeur, compte résilié, rançongiciel). <code>teuthis etat</code> et l&#39;installateur le rappellent à chaque fois, et la copie distante guidée avait été annoncée « juste après le premier jalon ». Le référent informatique visé n&#39;est pas un développeur : il doit pouvoir envoyer ses sauvegardes chez un hébergeur de son choix en répondant à quelques questions, et savoir si ça marche.</p><p>Trois exigences du Product Owner structurent la décision : l&#39;hébergeur de la copie ne doit <strong>rien pouvoir lire</strong> ; une copie injoignable ou en échec ne doit <strong>jamais</strong> passer inaperçue ; et un <strong>serveur perdu</strong> doit se relever à partir de la seule copie et d&#39;un mot de passe gardé ailleurs.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>1. L&#39;outil est restic</strong>, image officielle <code>restic/restic</code> (0.19.1, dernière version stable), <strong>épinglée par empreinte</strong> d&#39;index multi-architecture comme les autres images de la pile. Un seul outil copie, purge, vérifie et restaure ; son dépôt est chiffré de bout en bout (AES-256) et dédupliqué ; les backends S3 compatible et SFTP sont natifs.</p><p><strong>2. Un service dédié <code>copie-distante</code>, sans socket Docker.</strong> Le conteneur <code>sauvegarde</code> (image PostgreSQL) ne peut pas lancer restic : il n&#39;a pas son binaire, et surtout pas de client SSH, dont restic a besoin pour SFTP (il lance <code>ssh -s sftp</code>). Deux pistes ont été comparées :</p><table tabindex="0"><thead><tr><th>Piste</th><th>Retenue ?</th></tr></thead><tbody><tr><td>Un service d&#39;initialisation qui recopie <code>/usr/bin/restic</code> dans un volume lu par <code>sauvegarde</code></td><td>Non. Elle ne résout pas SFTP (il faudrait aussi recopier ssh et ses bibliothèques, ou l&#39;installer dans une image épinglée), ajoute un service éphémère, un volume et un <code>depends_on: service_completed_successfully</code>, et donnerait au conteneur qui détient le mot de passe de la base les identifiants de la destination distante.</td></tr><tr><td><strong>Un service <code>copie-distante</code> à l&#39;image restic, qui surveille les sauvegardes</strong></td><td><strong>Oui.</strong> L&#39;image porte restic, le client SSH, les certificats et un shell : rien à recopier ni à installer. Les privilèges se séparent : <code>sauvegarde</code> garde la base, <code>copie-distante</code> ne voit que les sauvegardes (qu&#39;il lit), les secrets de la copie et son propre script — pas le dossier de la pile, donc pas le <code>.env</code>. Aucun conteneur ne peut en commander un autre.</td></tr></tbody></table><p>Le service exécute <code>deploy/copie-distante.sh</code> (POSIX sh, livré dans l&#39;archive de la pile). Il observe <code>SAUVEGARDES</code> toutes les 30 secondes : dès qu&#39;une sauvegarde complète plus récente que la dernière copiée apparaît (sauvegarde nocturne <strong>ou</strong> <code>teuthis sauvegarder</code>), il la copie. Le déclenchement « juste après la sauvegarde » est donc au plus de 30 secondes. Il a un système de fichiers en lecture seule, aucune capacité Linux, 512 Mo de mémoire (restic en demande pour purger), et un cache dans un volume nommé qui se reconstruit.</p><p><strong>3. Chiffrement côté serveur, avant l&#39;envoi.</strong> C&#39;est le chiffrement natif de restic : la destination ne reçoit que des blocs chiffrés. Le mot de passe du dépôt est <strong>généré à la configuration</strong> (32 caractères d&#39;un alphabet de 32 sans caractère ambigu, soit 160 bits, groupés par quatre) et <strong>affiché une seule fois</strong>, à part, comme la clé d&#39;installation, avec la consigne de le garder <strong>hors du serveur</strong> : sans lui la copie est illisible, pour tout le monde, hébergeur compris, et il n&#39;existe aucun recours.</p><p><strong>4. Où vit le mot de passe : un fichier <code>copie-distante/mot-de-passe</code>, en 600, dans un dossier 700 de la pile — pas dans le <code>.env</code>.</strong> Le <code>.env</code> est relu par Compose (visible dans <code>docker compose config</code>), recopié dans <code>pile.tar.gz</code>, donc dans <strong>chaque sauvegarde</strong> — y compris celle qui part chez l&#39;hébergeur, avec la clé qui la déchiffre —, et montré (masqué) par le diagnostic. Le fichier, lui :</p><ul><li>n&#39;est monté que dans <code>copie-distante</code> (jamais dans l&#39;environnement du conteneur : ni <code>docker inspect</code>, ni <code>ps</code>) ;</li><li>est <strong>exclu de <code>pile.tar.gz</code></strong> (<code>--exclude=./copie-distante</code>) : aucun secret de la copie ne voyage avec une sauvegarde ;</li><li>est masqué par <code>teuthis diagnostic</code>, qui range aussi les identifiants S3 et le corps de la clé privée dans la liste des valeurs purgées de tout le fichier ;</li><li>n&#39;est jamais écrit dans un journal ni affiché une seconde fois. Les identifiants S3 (<code>acces-s3</code>) et la clé SSH (<code>id_ed25519</code>) suivent la même règle. Un mot de passe ou un secret <strong>en argument</strong> est refusé (« lisible dans <code>ps</code> ») : les identifiants S3 viennent de variables ou d&#39;une question sans écho, le mot de passe d&#39;un dépôt existant de l&#39;entrée standard (<code>--mot-de-passe-existant</code>).</li></ul><p><strong>5. Configuration guidée : <code>teuthis copie-distante configurer</code>.</strong> Questions (S3 : point d&#39;accès, région, compartiment, préfixe, identifiants ; SFTP : hôte, port, utilisateur, chemin), ou options et variables <code>TEUTHIS_COPIE_*</code> pour un script. Tout est contrôlé (formes, caractères), puis <strong>essayé avant d&#39;être enregistré</strong> : connexion, création du dépôt (<code>restic init</code>) ou ouverture d&#39;un dépôt existant, <strong>écriture d&#39;un instantané d&#39;essai</strong>, aussitôt retiré. L&#39;essai se fait dans <code>copie-distante/.essai/</code> ; la configuration actuelle n&#39;est remplacée qu&#39;après sa réussite. Les échecs se distinguent (aucun dépôt, mot de passe refusé, injoignable, écriture refusée, empreinte refusée) et chacun dit quoi faire. Pour SFTP : une clé ed25519 <strong>dédiée</strong> est créée (la privée ne quitte jamais le serveur, la publique est affichée à déposer chez le fournisseur) et l&#39;<strong>empreinte de l&#39;hôte est vérifiée puis enregistrée</strong> dans <code>known_hosts</code> — l&#39;exploitant la compare à celle de son fournisseur ; sans terminal, <code>--empreinte-hote</code> est obligatoire. <code>StrictHostKeyChecking=no</code> n&#39;existe nulle part : un hôte réinstallé ou interposé est refusé.</p><p><strong>6. Conservation distante et vérification.</strong> Après chaque copie : <code>forget --keep-daily 7 --keep-weekly 4 --keep-monthly 6 --prune</code>. Une fois par jour, après une copie réussie : <code>restic check --read-data-subset=N/10</code>, un dixième des données, un dixième différent chaque jour — le dépôt entier est relu en dix jours, pour un coût borné. <code>teuthis copie-distante verifier</code> le lance à la demande.</p><p><strong>7. Livré inactif, refus explicite, échec visible (ADR-0027).</strong></p><ul><li>Pas de <code>depot.conf</code> : rien n&#39;est contacté, le service est sain, aucun message d&#39;erreur.</li><li>Configuré mais illisible (type inconnu, fichier manquant, port illisible) : le service <strong>refuse de démarrer</strong> en disant pourquoi.</li><li>Configuré mais injoignable, mot de passe refusé, purge ou vérification en échec : <code>COPIE-DISTANTE-ECHEC.txt</code> (dans le dossier des sauvegardes, avec son type : copie, vérification, configuration) et le service <code>copie-distante</code> <strong>et</strong> <code>sauvegarde</code> passent <code>unhealthy</code>. Une copie réussie ne cache pas une vérification en échec. Après un échec, une tentative toutes les 30 minutes.</li><li><strong>Tout appel réseau a un délai.</strong> Un contrôle d&#39;ouverture du dépôt de 60 secondes précède chaque copie (restic réessaie une destination muette pendant un quart d&#39;heure), les essais de configuration sont bornés à 2 minutes, la copie à 6 heures.</li><li>Un échec de la seule copie distante <strong>ne bloque pas</strong> <code>mettre-a-jour</code> et ne déclenche pas son retour arrière : le serveur de copie en panne n&#39;est pas un défaut de l&#39;instance.</li></ul><p><strong>8. Surveillance.</strong> <code>teuthis etat</code> a une section « Copie distante » : « non configurée » avec le rappel « SUR CE SERVEUR », ou la destination, la dernière copie réussie (âge en heures, alerte au-delà de 26 h) et l&#39;échec en cours. <code>teuthis diagnostic</code> ajoute l&#39;état de la copie, sans aucun secret. <code>teuthis copie-distante etat</code> n&#39;affiche que cette section.</p><p><strong>9. Restauration : <code>teuthis restaurer --distante</code>.</strong> Sans nom, liste les copies du dépôt (date, taille). Avec un nom (ou <code>dernier</code>), rapatrie la copie dans <code>sauvegardes/</code>, revérifie ses sommes SHA256, puis <strong>réutilise le chemin de restauration existant</strong> (confirmation, arrêt des services, transaction unique, relance, santé). Sur un <strong>serveur perdu</strong> : installer à neuf la même version, <code>teuthis copie-distante configurer --mot-de-passe-existant</code>, puis <code>teuthis restaurer --distante &lt;nom&gt; --avec-pile</code>. <code>--avec-pile</code> ramène alors aussi le <code>.env</code> d&#39;origine (identifiant de l&#39;organisation, clés) même à version égale ; <strong>deux réglages restent ceux du serveur neuf</strong> — le mot de passe PostgreSQL du volume existant, que la sauvegarde d&#39;un autre serveur ne connaîtrait pas, et le dossier des sauvegardes.</p><p><strong>10. Preuve en CI.</strong> Un job <code>copie-distante</code> (<code>.github/scripts/verifier-copie-distante.sh</code>) fait tourner la vraie chaîne contre un MinIO et un serveur SFTP d&#39;essai, épinglés par empreinte : configuration non interactive, copie automatique, <strong>dépôt chiffré</strong> (aucune chaîne connue de la base en clair dans les objets), liste, vérification, MinIO arrêté → conteneurs <code>unhealthy</code> et <code>teuthis etat</code> qui le dit, <strong>instance neuve</strong> (volumes effacés) restaurée depuis la copie avec le mot de passe, hôte SFTP à l&#39;empreinte changée refusé. Les tests bats (<code>copie-distante.bats</code>, <code>teuthis.bats</code>) exercent chaque message, le refus d&#39;un mot de passe en argument, la politique de purge et la restauration distante avec un faux restic.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><code>rclone</code> seul, ou <code>rsync</code> / <code>scp</code> des dossiers</td><td>Aucun chiffrement de bout en bout, ni déduplication, ni vérification d&#39;intégrité : l&#39;hébergeur lirait la base. Il faudrait ajouter <code>age</code> ou GPG et gérer purge et restauration soi-même.</td></tr><tr><td>`pg_dump</td><td>gpg` puis envoi</td></tr><tr><td>Borg</td><td>Pas de backend S3 natif ; SFTP exige borg sur l&#39;hôte distant, ce qu&#39;un stockage de fournisseur n&#39;offre pas.</td></tr><tr><td>Binaire restic recopié dans <code>sauvegarde</code> par un service d&#39;initialisation</td><td>Voir la décision n°2 : ne résout pas SFTP et mélange les secrets.</td></tr><tr><td>Monter le socket Docker pour que <code>sauvegarde</code> lance un conteneur restic</td><td>Refusé : un socket monté donne le contrôle de l&#39;hôte. Aucun conteneur de la pile n&#39;en a.</td></tr><tr><td>Mot de passe et accès dans le <code>.env</code></td><td>Voir la décision n°4 : ils voyageraient dans chaque sauvegarde, et l&#39;hébergeur recevrait la clé de ses propres données.</td></tr><tr><td>Mot de passe choisi par l&#39;exploitant</td><td>Un mot de passe faible chiffre mal ; l&#39;exploitant le réutiliserait ailleurs. Il garde la main pour un dépôt existant (<code>--mot-de-passe-existant</code>).</td></tr><tr><td>Accepter l&#39;empreinte SSH à la première connexion (« trust on first use »)</td><td>Un hôte interposé à ce moment-là serait cru pour toujours. L&#39;exploitant compare l&#39;empreinte à celle de son fournisseur.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Une perte du serveur ne perd plus les sauvegardes : on réinstalle, on rouvre le dépôt avec le mot de passe, on restaure — procédure éprouvée en CI.</li><li>L&#39;hébergeur ne lit rien ; un échec ou une copie vieille de plus de 26 h se voit à <code>teuthis etat</code>, au conteneur <code>unhealthy</code> et au diagnostic.</li><li>Une installation qui ne configure rien n&#39;appelle toujours personne.</li></ul><p><strong>Négatives</strong></p><ul><li><strong>Un mot de passe perdu rend la copie irrécupérable.</strong> C&#39;est le prix du chiffrement de bout en bout ; la consigne est dite à l&#39;écran, dans le guide et dans « Dépannage ».</li><li><strong>Un service de plus</strong> (<code>copie-distante</code>, 512 Mo plafonnés) et une image de plus à surveiller.</li><li><strong>La déduplication est faible</strong> : les sauvegardes locales sont des archives compressées (<code>base.dump</code>, <code>.tar.gz</code>) qui changent presque entièrement d&#39;une nuit à l&#39;autre. Le dépôt distant pèse à peu près la somme des copies conservées. Copier les données non compressées est une évolution possible de la sauvegarde locale.</li><li><strong>La copie part au plus tard 30 secondes après la sauvegarde</strong>, pas dans la même seconde ; elle reste en retard tant que la précédente n&#39;est pas finie.</li><li>Les copies déjà envoyées restent chez le fournisseur après <code>desactiver</code> : les supprimer est l&#39;affaire de l&#39;exploitant.</li><li>Le serveur MinIO d&#39;essai de la CI vient d&#39;une image Bitnami « legacy » (figée) : MinIO ne publie plus d&#39;image sur Docker Hub ni Quay. C&#39;est un outil d&#39;essai jetable, jamais déployé.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Service <code>copie-distante</code>, script, configuration guidée, essai de connexion et d&#39;écriture avant enregistrement, mot de passe généré et affiché une fois, stockage en 600 hors <code>.env</code>, refus d&#39;un mot de passe en argument. — <code>deploy/copie-distante.sh</code>, <code>deploy/compose.yml</code> (service <code>copie-distante</code>, image restic épinglée, volume <code>cache-restic</code>, sondes de santé), <code>deploy/teuthis</code> (<code>copie-distante configurer|etat|essayer|verifier|cle-ssh|desactiver</code>), <code>deploy/sauvegarde.sh</code> (<code>--exclude=./copie-distante</code>, <code>pile.tar.gz</code> sans secret de la copie) ; preuves : <code>deploy/tests/copie-distante.bats</code> (39 tests : inactif par défaut, configuration illisible refusée, configuration S3 et SFTP, mot de passe affiché une seule fois et stocké en 600, refus en argument, purge <code>7/4/6</code>, délais, échec visible et levé, hôte à l&#39;empreinte changée refusé, masquage au diagnostic) et <code>.github/scripts/verifier-copie-distante.sh</code> (job <code>copie-distante</code> de la CI) — script exécuté de bout en bout en local le 13/10/2026 avec un vrai Docker (restic 0.19.1, MinIO et SFTP d&#39;essai, code 0) : <strong>preuve CI confirmée</strong> : job <code>copie-distante</code> vert sur le commit <code>524b1d0</code> (run 38443481761, 13/10/2026), après deux correctifs révélés sous Linux (attente du verrou, relevé unique des clés SFTP).</li><li>[x] Surveillance et restauration : <code>teuthis etat</code> et <code>diagnostic</code>, conteneurs <code>unhealthy</code>, <code>restaurer --distante</code>, procédure « serveur perdu ». — <code>deploy/teuthis</code>, <code>deploy/LISEZMOI.md</code> (« Copie distante », « Serveur perdu », « Dépannage ») ; preuves : 9 nouveaux tests dans <code>deploy/tests/teuthis.bats</code> (liste, rapatriement et restauration dans cet ordre, copie altérée refusée, serveur neuf avec mot de passe PostgreSQL conservé, <code>etat</code>, mise à jour non bloquée par la seule copie) et l&#39;étape « serveur perdu » du job <code>copie-distante</code> (instance neuve, volumes effacés, contenu retrouvé).</li><li>[x] Documentation : guide de l&#39;exploitant (<code>deploy/LISEZMOI.md</code>), notice (<code>docs/notice-utilisateur.md</code>), <code>deploy/.env.exemple</code>.</li><li>[ ] Recette contre un vrai fournisseur S3 (Scaleway, OVH, Backblaze…) et un vrai stockage SFTP, sur un serveur jetable (libellé <code>recette</code>) : la CI n&#39;a exercé que MinIO et OpenSSH locaux.</li><li>[ ] Remplacer le MinIO d&#39;essai par une image maintenue et épinglée quand MinIO en republiera une (ou par un autre serveur S3 d&#39;essai).</li><li>[ ] Évaluer l&#39;envoi de données non compressées (déduplication réelle, dépôt plus léger) : changerait le format des sauvegardes locales (ADR-0052).</li></ul>',29)])])}const v=t(o,[["render",n]]);export{g as __pageData,v as default};
